betas=pd.DataFrame(index=px.index,columns=syms,dtype=float)
for s in syms: betas[s]=r[s].rolling(60,min_periods=45).cov(dr)/dr.rolling(60,min_periods=45).var()
macro20=(dxy/dxy.shift(20)-1)
f=px.pct_change(20)-betas.mul(macro20,axis=0)
fr=r.shift(-1); ics=[]; dates=[]
for dt in f.index:
